# 광역시 + 세종
def mk(sido, sslug):
    def R(slug, name, alias, tags, intro, bld, areas, near):
        return dict(sido=sido, sslug=sslug, slug=sslug + '-' + slug, name=name, alias=alias, tags=tags,
                    intro=intro, bld=bld, areas=[tuple(a.split('|')) for a in areas],
                    near=[n if '-' in n else sslug + '-' + n for n in near])
    return R

